// Provisional domain types, until the PocketBase collections exist.
// TODO: replace with the types generated by pocketbase-typegen.

export type Hunt = {
  id: string;
  /** Local day of the hunt, `yyyy-MM-dd` (at most one hunt per day). */
  date: string;
  /** Meeting time, `HH:mm`. */
  meetingTime: string;
  /** Maximum number of participants; `null` when there is no limit. */
  maxParticipants: number | null;
  /** Deadline for members' answers, ISO 8601 instant, before the hunt. */
  responseDeadline: string;
};

export type NewHunt = Omit<Hunt, 'id'>;
